def _local_edges(
    declarations: tuple[Declaration, ...],
    occurrence_id: StaticOccurrenceId,
    family: InstructionOutcomeFamily,
) -> tuple[LocalEdge, ...]:
    result = []
    for outcome in family.outcomes:
        guard = z3.And(family.source_guard, outcome.guard)
        target: int | z3.BitVecRef = (
            outcome.target_value
            if outcome.target_value is not None
            else outcome.target
        )
        result.append(
            LocalEdge(
                id=EdgeId(
                    occurrence_id,
                    OutcomeId(outcome.identity.outcome_id),
                ),
                source=family.source,
                summary=step_summary_from_z3(
                    declarations,
                    guard=guard,
                    updates=outcome.updates,
                    target=target,
                    mirrored_pc=outcome.updates["rip"],
                ),
            )
        )
    return tuple(result)

