def _target_value(
    target: TypedExpr,
    declarations: tuple[Any, ...],
) -> int | None:
    ctx = z3.Context()
    variables = declaration_variables(declarations, ctx)
    expression = z3.simplify(expr_to_z3(target, variables, ctx))
    if z3.is_bv_value(expression):
        return expression.as_long()
    return None

