def replace_pending(path: _Pending, **changes: Any) -> _Pending:
    values = {
        "function_id": path.function_id,
        "pc": path.pc,
        "guard": path.guard,
        "state": path.state,
        "calls": path.calls,
        "edges": path.edges,
        "steps": path.steps,
    }
    values.update(changes)
    return _Pending(**values)

