def declaration_variables(
    declarations: tuple[Declaration, ...],
    ctx: z3.Context,
) -> dict[str, z3.ExprRef]:
    """Create one shared Z3 variable environment for semantic comparison."""

    result: dict[str, z3.ExprRef] = {}
