def _fold(op: str, args: tuple[TypedExpr, ...], identity: bool) -> TypedExpr:
    if not args:
        return TypedExpr.bool_lit(identity)
    result = args[0]
    for arg in args[1:]:
        result = TypedExpr.binary(op, result, arg)
    return result

