def _index(
    values: tuple[T, ...],
    key: Callable[[T], Any],
    field: str,
) -> dict[Any, T]:
    result: dict[Any, T] = {}
    for value in values:
        item_key = key(value)
        if item_key in result:
            raise ArtifactError(f"duplicate {field}: {item_key!r}")
        result[item_key] = value
    return result

